attempts.script:
# Get all nets
set all_nets [get_nets -hierarchical]

# Open output file
set output_file "outputs/unloaded_nets.txt"
file delete -force $output_file
set fid [open $output_file w]

# Get all top-level output ports
set top_out_ports [get_ports -direction out]

foreach net $all_nets {
    set net_name [get_name $net]

    # Get drivers (output pins connected to this net)
    set drivers [get_pins -hierarchical -filter "net == $net_name && direction == out"]

    # If no driver, skip
    if {[llength $drivers] == 0} {
        continue
    }

    # Get cell input pins connected to this net
    set cell_inputs [get_pins -hierarchical -filter "net == $net_name && direction == input"]

    # Get top-level output port pins connected to this net
    set port_loads {}
    foreach port $top_out_ports {
        set port_pin [get_pins -of_objects [get_ports $port]]
        if {[llength $port_pin] > 0} {
            set port_net [get_net -of_objects $port_pin]
            if {[get_name $port_net] == $net_name} {
                lappend port_loads $port
            }
        }
    }

    # If no cell input loads and no top-level output port loads, it's unloaded
    if {[llength $cell_inputs] == 0 && [llength $port_loads] == 0} {
        # There might be multiple drivers, pick one? The task says "any order" for lines, but for a net, 
        # if there are multiple drivers, which one to report? 
        # The task says "<net_name> <driver_instance>/<driver_pin>". It implies one line per net? 
        # "one line per such net". So we should pick one driver.
        set driver [lindex $drivers 0]
        set driver_instance [get_property $driver instance]
        set driver_pin [get_property $driver name]
        puts $fid "$net_name $driver_instance/$driver_pin"
    }
}

close $fid
